"""Tests for the config reference generator (build-scripts/configdocs.py)."""

from typing import Literal

import pytest
from configdocs import generate_table, splice_section, table_cell
from pydantic import Field

from nbkp.config import LocalVolume, LuksEncryptionConfig
from nbkp.config.protocol.base import ConfigModel

_BEGIN = (
    "<!-- BEGIN S (auto-generated by: mise run configdocs — do not edit manually) -->"
)
_END = "<!-- END S -->"


class TestSpliceSection:
    def test_replaces_the_span_between_the_markers(self) -> None:
        doc = f"before\n{_BEGIN}\nold\n{_END}\nafter\n"

        assert splice_section(doc, "S", "new\n") == (
            f"before\n{_BEGIN}\nnew\n{_END}\nafter\n"
        )

    @pytest.mark.parametrize(
        "doc",
        [
            pytest.param(f"{_BEGIN}\nold\n", id="missing-end"),
            pytest.param(f"{_END}\nold\n{_BEGIN}\n", id="end-before-begin"),
            pytest.param(f"{_BEGIN}\n{_END}\n{_BEGIN}\n{_END}\n", id="repeated"),
            pytest.param(f"{_BEGIN}\nold\n{_END}\nprose\n{_END}\n", id="stray-end"),
        ],
    )
    def test_exits_on_unusable_markers(self, doc: str) -> None:
        with pytest.raises(SystemExit):
            splice_section(doc, "S", "new\n")


class TestTableCell:
    def test_escapes_pipes(self) -> None:
        assert table_cell("`a | b` or c") == "`a \\| b` or c"


class _Documented(ConfigModel):
    slug: str
    type: Literal["local"]
    max_count: int = Field(default=3, ge=1, description="How | many")  # noqa: DC06 -- a documented field
    renamed: str = Field(alias="explicit-key", description="Aliased")  # noqa: DC06 -- a documented field


class TestGenerateTable:
    def test_documents_each_field_under_its_config_key(self) -> None:
        assert generate_table(_Documented).splitlines() == [
            "| Field | Type | Default | Description |",
            "|---|---|---|---|",
            '| `type` | `"local"` | **required** |  |',
            "| `max-count` | integer (>= 1) | `3` | How \\| many |",
            "| `explicit-key` | string | **required** | Aliased |",
        ]


class TestDiscriminatorRows:
    def test_volume_type_is_required(self) -> None:
        rows = generate_table(LocalVolume).splitlines()
        assert (
            '| `type` | `"local"` | **required** | Volume type discriminator |' in rows
        )

    def test_encryption_type_keeps_its_own_default_and_description(self) -> None:
        row = generate_table(LuksEncryptionConfig).splitlines()[2]
        assert row.startswith('| `type` | `"luks"` | `"luks"` | Encryption backend')
